    {
        [TestMethod]
        public void Each_Service_Should_Have_A_Registration_Extension_In_The_Same_File()
        {
            var missingServiceRegistrations = (from service in Services
                                               where service.Registration is null
                                               select new
                                               {
                                                   Error = $@"
Your service:       {service.Class.Name} does not have a service registration declared in same file. 
                    If it is in same file please check the name
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullQualifiedName:  {service.Class.FullQualifiedName}.{service.Class.Name}'
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:             

{service.Class.BuildServiceRegistration(Classes)}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                               }).ToImmutableList();

            Assert.IsTrue(missingServiceRegistrations.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_S_00001

Missing service registrations. Findings {missingServiceRegistrations.Count}': {Environment.NewLine}{missingServiceRegistrations.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
